import {store,pocket,url,asset,params,evidenceArticle,sourceBody,commandForm,mountPage,recordTable,downloadLocal,truth,esc} from '../arg-ui.js?v=44';
import {EVIDENCE,MATERIALS,SPRING_BV,AUDIT_EDGES} from '../arg-content.js?v=43';
import {truthy,owned,canRead} from '../arg-engine.js?v=44';
import {decryptArchive,workbookBlob} from '../archive-crypto.js?v=43';
const app=document.querySelector('#app');let fragments=[];
function frame(body){app.innerHTML=`<section class="pan-site"><header class="pan-header"><a href="index.html"><b>▰</b> 青禾网盘</a><span>班级资料与授权副本</span><small>只读分享</small></header><div class="pan-layout"><aside><a href="index.html">公开资料树</a><p>文件由上传者分享。受保护文件夹沿用各自提取规则。</p></aside><div class="pan-main">${body}</div></div><footer>青禾网络信息中心 · 2018校内资料平台</footer></section>`;}
const a=(folder,label)=>`<a class="pan-recent" href="index.html?folder=${folder}">▰ ${label}</a>`;
function login(folder,account,note){frame(`<h1>${esc(note)}</h1><form id="folderLogin" class="pan-extract"><label>账号<input name="user" value="${account==='azhe'?'heshe':account==='jie'?'jiege':account}" readonly></label><label>口令<input name="password" type="password" autocomplete="off" ${account==='makeup'?'placeholder="月日+时间(如03281430)" inputmode="numeric"':''} required></label><button>打开资料夹</button><p data-response></p></form><div class="arg-upstream">${account==='jie'?`<p>口令规则在取餐存根背面；实际值日与寝室门牌在旧账帖。</p>${sourceBody(MATERIALS.caseDocs.pickup.body)}`:account==='yida'?sourceBody(MATERIALS.caseDocs['sports-slip'].body):account==='azhe'?sourceBody(MATERIALS.caseDocs['editor-note'].body):'<p>补测通知：3月28日14:30，口令为月日接时间。</p>'}<p><a href="${url('forum',{q:account==='jie'?'夜宵账单':account==='yida'?'旧照片':'打印委托'})}">翻相应的论坛历史资料 →</a></p></div>`);commandForm(app.querySelector('form'),'login',d=>({account,password:d.get('password')}));}
function privateFolder(folder){const account=folder==='heshe'?'azhe':folder;if(!truthy(store.get(),'accounts',account))return login(folder,account,`${folder==='heshe'?'《禾声》阅览':folder==='makeup'?'班级补测':folder==='jie'?'杰哥':'益达'}资料夹`);const list={jie:['mealPhoto','flow'],yida:['deletion','yidaResult'],heshe:['submission','withdrawal'],makeup:['examNotice','lin']}[folder];frame(`<h1>${folder==='heshe'?'禾声收稿留存':'授权资料'}</h1>${list.map(id=>evidenceArticle(id,{compact:true})).join('')}${folder==='jie'?'<details><summary>语文资料_最终版.png</summary><p>PHIGROS / 0948721 / Accuracy 94.87%。杰哥说这张就够了，前面打了几次别问，也别跟老师说。</p></details>':''}${folder==='yida'?'<details class="arg-private-letter"><summary>益达保留的那封旧信（仅宿舍回忆）</summary><p>室友笑称它为“圣经”。原信一直由益达保存，没有借给别人。</p><blockquote>我以前不喜欢你，以后也不会喜欢你。</blockquote><p>“差不多得了，别拍。”他说。</p></details>':''}<p><a href="${url('forum',{view:'compare'})}">报告图像比对</a>　<a href="${url('forum',{thread:'chen'})}">把材料拿去问朱贵</a></p>`);}
function share(folder){if(!truthy(store.get(),'accounts',folder)){frame(`<h1>${folder==='spring'?'春季接力与学生会交接':'秋季运动会源素材'}</h1><form id="shareForm" class="pan-extract"><label>提取码<input type="password" name="code" required aria-describedby="shareCodeFeedback" autocomplete="off"></label><p>按视频简介的顺序核对拍摄日期和地点／机位。</p><button>提取文件</button><p id="shareCodeFeedback" data-response role="status" aria-live="polite"></p></form>`);commandForm(app.querySelector('form'),'share',d=>({folder,code:d.get('code')}));return;}
 if(folder==='spring')frame(`<h1>春季接力原素材 / 器材交接</h1><figure class="pan-frame-preview" data-evidence="printerRegister"><img src="${asset('video/frames/spring-03.svg')}" alt="3月14日学生会打印机搬运原帧"><figcaption>2025-03-14 14:26:24。场记确认左侧为朱贵，另一人为阉鸡；不能只凭弹幕辨认。</figcaption></figure><article class="arg-doc-text" data-evidence="printerRegister"><p>交接簿：2025-03-14 14:20—14:35，学生会XSH器材处，打印机QH-P02。搬运：朱贵、阉鸡；摄影场记：mj，原始卡片编号SP0314-03。</p><p>登记只证明到过这个地点、接触过设备。改报告还要核对本人原图、原始投稿与打印委托。</p></article><button data-download-frame>下载原始关键帧SVG</button><p><a href="${url('forum',{thread:'printing'})}">核对3月17日打印委托</a>　<a href="${url('forum',{thread:'leave'})}">核对请假说法</a></p>`);else frame(`<h1>秋季运动会底片交接</h1><figure class="pan-frame-preview" data-evidence="relayRegister"><img src="${asset('assets/class-photo.svg')}" alt="受保护的班级合照缩略复印件，10月18日B机正式场"><figcaption>班级合照 / 仅在原作者提供的提取范围内可见。</figcaption></figure><div data-evidence="relayRegister"><p>10月17日A机试拍；10月18日B机正式比赛；10月19日C机补拍。视频上传于10月20日，不能替代拍摄日。</p><img class="arg-small-image" src="${asset('video/frames/autumn-03.svg')}" alt="秋季场记B机"></div><p><a href="index.html?folder=yida">回照片领取单核对</a></p>`);app.querySelector('[data-download-frame]')?.addEventListener('click',async()=>{const r=await fetch(asset('video/frames/spring-03.svg'));if(r.ok)downloadLocal(await r.text(),'SP0314-03.svg','image/svg+xml');});}
function clinic(file){if(!truth(store.get()).first){frame('<h1>此分享尚未交付</h1><p>请从原作者提供的入口进入。</p>');return;}
 if(!truthy(store.get(),'accounts','shenzhi')){frame(`<h1>小范的授权资料柜</h1>${evidenceArticle('authorization',{compact:true})}<p>首次值班时间与末曲分开留存：</p><p><a href="${url('forum',{thread:'oldpost'})}">周五值班旧帖</a>　<a href="${url('forum',{thread:'radio'})}">广播站排期</a></p><form id="recoverForm" class="pan-extract"><label>第一次值班那天的最后一首歌<select name="song" required><option value="">请选择</option><option>平凡之路</option><option>稻香</option><option>夜空中最亮的星</option></select></label><button>找回授权阅览</button><p data-response></p></form>`);commandForm(app.querySelector('form'),'recover');return;}
 if(file&&EVIDENCE[file]){frame(evidenceArticle(file)+`<p>${a('clinic','回医务室目录')}</p><p><a href="index.html?folder=clinic&file=medication">检测前用药核对页</a>　<a href="${url('canteen',{view:'summary'})}">后勤汇总底稿</a>　<a href="${url('canteen',{view:'timeline'})}">草稿所列到场记录</a></p>${file==='medical'||file==='medication'?medicalForm():file==='cache'?'<a href="index.html?folder=cache">打开缓存片段恢复页 →</a>':''}`);if(app.querySelector('#medicalForm'))commandForm(app.querySelector('#medicalForm'),'medical');return;}
 frame(`<h1>小范 / 离职前导出的工作副本</h1><p>材料可以分别查看，不按页面顺序解锁。</p><div class="arg-file-tree">${['draft','medical','medication','cache'].map(id=>`<a href="index.html?folder=clinic&file=${id}">▤ ${esc(EVIDENCE[id].title)}</a>`).join('')}<a href="${url('canteen',{view:'summary'})}">↗ 后勤健康汇总底稿</a><a href="${url('canteen',{view:'timeline'})}">↗ 后勤到场记录核查</a></div>${evidenceArticle('draft',{compact:true})}<p><a href="index.html?folder=cache">查看本地草稿缓存 →</a></p><p><a href="index.html?folder=audit">草稿引用的附件目录 →</a></p>`);
}
function medicalForm(){return `<form id="medicalForm" class="arg-local-question"><h2>这几张单子能说明什么？</h2>${truthy(store.get(),'actions','medicalChecked')?'<p class="arg-verified">✓ 这组质疑已核对，来源仍可重读。</p>':''}<p>送达记录还有R09复查阳性、R12待复查。汇总没有列入这些后续材料。</p><label>哪份初检需要核对准备情况？<select name="patient"><option value="">请选择</option><option>R07</option><option>R09</option><option>R12</option></select></label><label>该记录复查月日<input name="repeat" placeholder="月日，例如0329" required></label><label>初检判断<select name="interpretation"><option value="safe">阴性就完全排除</option><option value="unreliable">检测前用药影响可靠性，不能据此排除</option><option value="new">复查阳性就说明刚刚感染</option></select></label><label>能否反推感染批次？<select name="batch"><option value="order">可按DOB高低排序</option><option value="unknown">不能，只核对检测可靠性和收文时间</option></select></label><button>写下医疗材料质疑</button><p data-response></p></form>`;}
function cache(){if(!canRead(store.get(),'cache'))return clinic();frame(`<h1>草稿D0329 / 本地自动保存</h1>${evidenceArticle('cache',{compact:true})}<div class="arg-fragments">${MATERIALS.cacheFragments.map(f=>`<button type="button" data-fragment="${f.id}" class="${fragments.includes(f.id)?'selected':''}"><small>${f.draft} / 修订${f.revision} / ${f.part} / ${f.time}</small><span>${f.text}</span></button>`).join('')}</div><p>已选：${fragments.join(' → ')||'无'}</p><button data-restore>按所选顺序恢复</button><button data-clear>清空重排</button><p data-response></p>${truthy(store.get(),'actions','cacheRestored')?`<article class="arg-restored">${MATERIALS.cacheFragments.filter(f=>f.id==='d2-head'||f.id==='d2-tail').sort((a,b)=>a.part.localeCompare(b.part)).map(f=>`<p>${f.text}</p>`).join('')}<p><a href="index.html?folder=audit">打开核查附件目录</a>　<a href="${url('canteen',{view:'outage'})}">查草稿提到的配电工单</a></p></article>`:''}`);app.querySelectorAll('[data-fragment]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.fragment;fragments=fragments.includes(id)?fragments.filter(k=>k!==id):[...fragments.slice(-1),id];cache();import('../arg-ui.js?v=44').then(m=>m.watchReads());}));app.querySelector('[data-clear]').onclick=()=>{fragments=[];cache();};app.querySelector('[data-restore]').onclick=()=>pocket.feedback(store.dispatch('restore',{fragments}).message);}
function audit(){if(!truthy(store.get(),'actions','cacheRestored'))return frame('<h1>附件目录未核实</h1><p>需要先从授权草稿确认附件编号及修订出处。</p>');const s=store.get();frame(`<h1>后勤核查 / L-0313消杀与结算原导出包</h1><div class="arg-file-tree"><a href="index.html?folder=blackboard">▧ 黑板报公开照片</a>${['lab-original','lab-edited','settlement'].map(id=>`<a href="index.html?folder=archive&file=${id}">▤ ${esc(EVIDENCE[id].title)}</a>`).join('')}<a href="${url('canteen',{view:'contract'})}">↗ 外包补充协议</a><a href="${url('canteen',{view:'outage'})}">↗ 设备停用工单归档</a></div>${s.vault?`<div data-evidence="ledger">${recordTable({...s.vault.value,title:'L-0313 消杀台账'},{key:'ledger',interactive:true,selected:s.marks.ledger?.value||[]})}</div><button data-workbook-download>下载原Excel（含结算附页）</button>`:'<div class="portal-error">预览失败：ERR_PREVIEW_NO_KEY。文件需要口令，刷新不能解开。</div>'}<form id="auditDecrypt" class="pan-extract"><label>原导出包口令<input name="password" type="password" maxlength="16" required></label><p>按原草稿的说明核对试运行日期，不使用开学日。</p><button>验证并解密</button><p data-response role="status"></p></form><p><a href="index.html?folder=review">查询原件复核回函</a>　<a href="index.html?folder=notice">处理意见与通报</a></p>`);app.querySelector('[data-workbook-download]')?.addEventListener('click',()=>downloadLocal(workbookBlob(store.get().vault.value),'L-0313_消杀与结算.xlsx'));
 app.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button'),out=e.target.querySelector('[data-response]'),password=new FormData(e.target).get('password');button.disabled=true;try{const response=await fetch(new URL('../assets/L-0313.enc.json?v=43',import.meta.url));if(!response.ok)throw Error('附件载入失败，请重试。');const payload=await decryptArchive(await response.json(),password);const r=store.dispatch('vault',{payload});pocket.feedback(r.message);if(out.isConnected)out.textContent=r.message;}catch(error){if(out.isConnected)out.textContent=error.name==='OperationError'?'口令未通过验证，原件没有解开。':error.message;}finally{if(button.isConnected)button.disabled=false;}});
}
function notice(){const t=truth(store.get()),aDone=truthy(store.get(),'actions','endingA'),bDone=truthy(store.get(),'actions','endingB');frame(`<h1>青禾高中 / 通报与核查回复</h1>${!t.first?'<p>尚未形成需要本人确认的处理意见。</p>':`<article class="arg-notice"><h2>拟归档：个别学生饮食卫生问题</h2><p>“已核实两份结果，无新增待核材料。”这句话与已经签收的复查资料是否一致，签名前仍可继续核对。</p><button data-ending="A">A · 接受现有通报，先到这里</button></article><article class="arg-notice"><h2>完整问题清单与原件复核</h2><p>需要五组核心互证及出具单位、设备与财务复核回函。</p><a href="index.html?folder=review">查看复核材料</a><button data-ending="B">B · 提交完整清单，要求公开整改</button></article>`}${aDone?'<article class="arg-ending"><h2>A · 通报贴上去了</h2><p>学校仍以个人卫生归档。朱贵承认改图，却没能让被漏列的复查材料进入公开说明。你把签过的那页复印一份留着，调查本没有清空，仍可以补证。</p></article>':''}${bDone?'<article class="arg-ending"><h2>B · 公开整改</h2><p>出具单位核对存根，确认微生物项目未检；电工确认停电窗口；财务复核三笔验收付款。学校更正了“无新增待核”，重新登记后续材料，暂停相关验收，退还无法证明完成的对应服务分摊餐费。</p><p>公告没有写谁传给谁，也没有贴学生病历。益达在本子上补了一行：“这回总算不是先找谁背锅。”</p></article>':''}`);app.querySelectorAll('[data-ending]').forEach(b=>b.onclick=()=>pocket.feedback(store.dispatch('ending',{choice:b.dataset.ending}).message));}
mountPage(()=>{const p=params(),folder=p.get('folder')||'',file=p.get('file');if(['jie','yida','heshe','makeup'].includes(folder))privateFolder(folder);else if(['spring','relay'].includes(folder))share(folder);else if(folder==='clinic')clinic(file);else if(folder==='cache')cache();else if(folder==='audit')audit();else if(folder==='blackboard')frame(evidenceArticle('blackboard'));else if(folder==='archive')frame(evidenceArticle(file));else if(folder==='review')frame(evidenceArticle('auditReview')+'<p>本回函由相关原出具单位及学校复核记录汇总，不等同于玩家自行认定。<a href="index.html?folder=notice">查看处理意见</a></p>');else if(folder==='notice')notice();else frame(`<h1>班级资料 / 本人授权分享</h1><div class="arg-file-tree">${a('jie','杰哥的资料柜')}${a('yida','益达的旧资料')}${a('heshe','禾声收稿阅览')}${a('makeup','班级补测通知')}${truth(store.get()).first?a('clinic','小范的阅览授权'):''}</div><p>涉及事件的原帖：<a href="${url('forum',{thread:'reports'})}">三份检查材料的讨论</a>。源素材目录以原作者给出的分享链接为准。</p>`);});
